    os.makedirs(workdir, exist_ok=True)
    # create structure
    os.makedirs(os.path.join(workdir,"a/b/c/d"), exist_ok=True)
    for p in ["f1.txt","a/f2.txt","a/b/f3.txt","a/b/c/f4.txt","a/b/c/d/f5.txt"]:
