use clap::{Parser, ArgAction};
use regex::Regex;
use std::collections::{HashMap, HashSet, BTreeMap};
use std::ffi::OsStr;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

#[derive(Parser, Debug)]
#[command(name = "nomino", version = "1.6.4", about = "Batch rename utility for developers", override_usage = "executable [OPTIONS] [[SOURCE] OUTPUT]...")]
struct Args {
    #[arg(short = 'd', long = "dir", value_name = "PATH")]
