    #[arg(short = 'm', long = "map", alias = "from-file", value_name = "PATH")]
    map: Option<String>,

    #[arg(long = "max-depth", value_name = "DEPTH")]
    max_depth: Option<usize>,

    #[arg(short = 'q', long = "quiet", action = ArgAction::SetTrue)]
    quiet: bool,

    #[arg(short = 'r', long = "regex", value_name = "PATTERN")]
    regex: Option<String>,

    #[arg(short = 's', long = "sort", value_name = "ORDER")]
    sort: Option<String>,

    #[arg(short = 't', long = "test", alias = "dry-run", action = ArgAction::SetTrue)]
    test: bool,

    #[arg(short = 'w', long = "overwrite", action = ArgAction::SetTrue)]
    overwrite: bool,

    #[arg(value_name = "[SOURCE] OUTPUT", num_args = 0..)]
    positional: Vec<String>,
}

#[derive(Debug)]
struct OutputToken {
    is_placeholder: bool,
    literal: String, // for literal
    group: Option<String>, // for placeholder: None means auto
    padding: Option<usize>,
}

fn parse_output_pattern(pattern: &str) -> Result<Vec<OutputToken>, String> {
    let mut tokens: Vec<OutputToken> = Vec::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    let mut literal = String::new();
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            if i + 1 >= chars.len() {
                // lone backslash? In original, "\\" alone gave "\.txt" (backslash literal). Actually they treat "\\" as escaped backslash -> literal "\"
                // But "\" at end? Let's see. We handle escape sequences: only \{, \}, \\ are valid. Others error.
                return Err(format!("invalid escape character of ' ' at '{}'", i)); // placeholder, but we need proper
            }
            let next = chars[i+1];
            if next == '{' || next == '}' || next == '\\' {
                literal.push(next);
                i += 2;
            } else {
                return Err(format!("[output-format] invalid escape character of '{}' at '{}'", next, i+1));
            }
        } else if c == '{' {
            // flush literal
            if !literal.is_empty() {
                tokens.push(OutputToken { is_placeholder: false, literal: literal.clone(), group: None, padding: None });
                literal.clear();
            }
            // find closing }
            let mut j = i+1;
            let mut found = false;
            while j < chars.len() {
                if chars[j] == '}' {
                    found = true;
                    break;
                }
                // if we encounter unescaped { inside, it's allowed? The spec says {{0}} is error "unopened placeholder could not be closed". So nested { should cause error? We need to detect.
                // For simplicity, if we encounter '{' before '}', we will treat as error later.
                j+=1;
            }
            if !found {
                return Err("[output-format] all opened placeholders must be closed by '}'".to_string());
            }
            // content between i+1 and j
            let content: String = chars[i+1..j].iter().collect();
            // check for nested braces?
            if content.contains('{') {
                // The original for "{{0}}" gave "an unopened placeholder could not be closed by '}'"
                // For "{" alone, it gave "all opened placeholders must be closed"
                // For "{{0}}" pattern: chars = { { 0 } } . First { at 0, find } at 3? That would be "{{0}"? Actually "{{0}}" : positions 0:{,1:{,2:0,3:},4:}. The first { finds } at 3, content "{0" which contains '{' => error unopened placeholder could not be closed?
                // Let's implement: if content contains '{', then error unopened.
                // But also need to handle "}" alone error.
                return Err("[output-format] an unopened placeholder could not be closed by '}'".to_string());
            }
            // parse content: format G:P where G is group, P padding
            // Could be empty, or ":3", or "1", "1:3", "name", "name:3"
            let (group_part, padding_part) = if let Some(colon_idx) = content.find(':') {
                let g = &content[..colon_idx];
                let p = &content[colon_idx+1..];
                (g, Some(p))
            } else {
                (content.as_str(), None)
            };
            let group_opt = if group_part.is_empty() {
                None
            } else {
                Some(group_part.to_string())
            };
            let padding_opt = if let Some(p_str) = padding_part {
                if p_str.is_empty() {
                    // "{1:}" case: p empty => no padding? In earlier test, "{1:}" gave 1.txt (no padding)
                    None
                } else {
                    // parse as usize, but must be digits only?
                    match p_str.parse::<usize>() {
                        Ok(v) => Some(v),
                        Err(_) => {
                            return Err(format!("[output-format] unable to parse padding of '{}'", p_str));
                        }
                    }
                }
            } else {
                None
            };
            tokens.push(OutputToken { is_placeholder: true, literal: String::new(), group: group_opt, padding: padding_opt });
            i = j+1;
        } else if c == '}' {
            // unescaped } without opening
            return Err("[output-format] an unopened placeholder could not be closed by '}'".to_string());
        } else {
            literal.push(c);
            i+=1;
        }
    }
    if !literal.is_empty() {
        tokens.push(OutputToken { is_placeholder: false, literal, group: None, padding: None });
    }
    Ok(tokens)
}

fn format_output(tokens: &[OutputToken], captures: &HashMap<String, String>, auto_counter: &mut usize, index: usize) -> String {
    // captures: maps group id (string) -> value, including "0" for full match, numeric strings for groups, and named groups
    // For sort mode, captures contains "0" = filename, "1" = index string etc? Actually we will provide mapping for groups including "0" filename and "1" index, but for auto placeholders we need to use auto_counter.
    // The auto_counter starts at 1 for each file (per README: auto incremental index starts from 1). For each placeholder where group is None, use auto_counter value as string? But also if group is omitted, it should map to group {auto_counter}? Let's interpret:
    // Placeholder {G:P} where G dropped => auto incremental index is used which starts from 1. For example, {} {} equals {1} {2}.
    // So {} without group should be replaced by capture group with index auto_counter, and then auto_counter increments by 1.
    // For sort mode, group "1" is index (1,2,3...). For regex mode, groups are 0,1,2,... named.
    // So auto placeholder: group = auto_counter to string, then increment.
    let mut result = String::new();
    for token in tokens {
        if !token.is_placeholder {
            result.push_str(&token.literal);
        } else {
            let group_key: String;
            if let Some(ref g) = token.group {
                group_key = g.clone();
            } else {
                group_key = auto_counter.to_string();
                *auto_counter += 1;
            }
            // lookup
            let mut val = captures.get(&group_key).cloned().unwrap_or_else(|| "".to_string());
            // padding: only for positive numbers
            if let Some(pad) = token.padding {
                // check if val is positive number
