fn print_table(entries: &[(String,String)]) {
    if entries.is_empty() {
        return;
    }
    // Compute max widths
    let mut max_input = "Input".len();
    let mut max_output = "Output".len();
    for (inp, out) in entries {
        if inp.len() > max_input {
            max_input = inp.len();
        }
        if out.len() > max_output {
            max_output = out.len();
        }
    }
    // Build border
    let border = format!("+{}+{}+", "-".repeat(max_input+2), "-".repeat(max_output+2));
    println!("{}", border);
    println!("| {} | {} |", pad_right("Input", max_input), pad_right("Output", max_output));
    println!("{}", border);
    for (inp, out) in entries {
        println!("| {} | {} |", pad_right(inp, max_input), pad_right(out, max_output));
    }
    println!("{}", border);
}

fn pad_right(s: &str, width: usize) -> String {
    // Left align, pad with spaces to width
    // Need to handle that s may contain unicode? We'll use chars count as bytes len for simplicity, but original uses byte len? For ascii it's same.
    // Use format with width.
    format!("{:<width$}", s, width = width)
