    }
    Ok(tokens)
}

fn format_output(tokens: &[OutputToken], captures: &HashMap<String, String>, auto_counter: &mut usize, index: usize) -> String {
    // captures: maps group id (string) -> value, including "0" for full match, numeric strings for groups, and named groups
    // For sort mode, captures contains "0" = filename, "1" = index string etc? Actually we will provide mapping for groups including "0" filename and "1" index, but for auto placeholders we need to use auto_counter.
