    // So {} without group should be replaced by capture group with index auto_counter, and then auto_counter increments by 1.
    // For sort mode, group "1" is index (1,2,3...). For regex mode, groups are 0,1,2,... named.
    // So auto placeholder: group = auto_counter to string, then increment.
    let mut result = String::new();
    for token in tokens {
        if !token.is_placeholder {
            result.push_str(&token.literal);
        } else {
            let group_key: String;
            if let Some(ref g) = token.group {
                group_key = g.clone();
            } else {
                group_key = auto_counter.to_string();
                *auto_counter += 1;
            }
            // lookup
            let mut val = captures.get(&group_key).cloned().unwrap_or_else(|| "".to_string());
            // padding: only for positive numbers
            if let Some(pad) = token.padding {
                // check if val is positive number
                // Try parse as i64? If positive, pad with zeros to width pad
                // The original: padding only used for positive numbers, e.g. formatted result for {:3} for 1 is 001, for -1 is -1 and for a is a.
                // So we need to check if val is positive integer (maybe including leading zeros already?). For our purposes, try to parse as i64.
                if let Ok(num) = val.parse::<i64>() {
                    if num >= 0 {
                        // pad
                        // If pad ==0? We saw {1:0} gave 1.txt (no pad). So pad width.
                        if pad > 0 {
                            // format with leading zeros
                            let s = num.to_string();
                            if s.len() < pad {
                                let zeros = "0".repeat(pad - s.len());
                                val = format!("{}{}", zeros, s);
                            }
                        }
                    }
                } else {
                    // if val is like "001"? Already? But it's numeric string, padding still?
                    // Try to parse as u64 maybe? But we already attempted i64 which would succeed for positive numbers.
                    // If not numeric, leave as is.
                }
            }
            result.push_str(&val);
        }
    }
    result
}

