fn natural_sort_key(s: &str) -> Vec<NaturalSortPart> {
    // For natural sort: split into chunks of digits and non-digits
    let mut parts: Vec<NaturalSortPart> = Vec::new();
    let mut chars = s.chars().peekable();
    while let Some(&c) = chars.peek() {
        if c.is_ascii_digit() {
            let mut num_str = String::new();
            while let Some(&d) = chars.peek() {
                if d.is_ascii_digit() {
                    num_str.push(d);
                    chars.next();
                } else {
                    break;
                }
            }
            // parse as number, but keep original for tie-breaking?
            let num = num_str.parse::<u64>().unwrap_or(0);
            parts.push(NaturalSortPart::Number(num, num_str));
        } else {
            let mut txt = String::new();
            while let Some(&d) = chars.peek() {
                if !d.is_ascii_digit() {
                    txt.push(d);
                    chars.next();
                } else {
                    break;
                }
            }
            parts.push(NaturalSortPart::Text(txt));
        }
    }
    parts
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
enum NaturalSortPart {
    Number(u64, String),
    Text(String),
}

