    fn parse_output_pattern(pattern: &str) -> Result<Vec<OutputToken>, String> {
        let mut tokens: Vec<OutputToken> = Vec::new();
        let chars: Vec<char> = pattern.chars().collect();
        let mut i = 0;
        let mut literal = String::new();
        while i < chars.len() {
            let c = chars[i];
            if c == '\\' {
                if i + 1 >= chars.len() {
                    return Err(format!("[output-format] invalid escape character of ' ' at '{}'", i));
                }
                let next = chars[i+1];
                if next == '{' || next == '}' || next == '\\' {
                    literal.push(next);
                    i += 2;
                } else {
                    return Err(format!("[output-format] invalid escape character of '{}' at '{}'", next, i+1));
                }
            } else if c == '{' {
                if !literal.is_empty() {
                    tokens.push(OutputToken { is_placeholder: false, literal: literal.clone(), group: None, padding: None });
                    literal.clear();
                }
                let mut j = i+1;
                let mut found = false;
                while j < chars.len() {
                    if chars[j] == '}' {
                        found = true;
                        break;
                    }
                    j+=1;
                }
                if !found {
                    return Err("[output-format] all opened placeholders must be closed by '}'".to_string());
                }
                let content: String = chars[i+1..j].iter().collect();
                if content.contains('{') {
                    return Err("[output-format] an unopened placeholder could not be closed by '}'".to_string());
                }
                let (group_part, padding_part) = if let Some(colon_idx) = content.find(':') {
                    let g = &content[..colon_idx];
                    let p = &content[colon_idx+1..];
                    (g, Some(p))
                } else {
                    (content.as_str(), None)
                };
                let group_opt = if group_part.is_empty() { None } else { Some(group_part.to_string()) };
                let padding_opt = if let Some(p_str) = padding_part {
                    if p_str.is_empty() {
                        None
                    } else {
                        match p_str.parse::<usize>() {
                            Ok(v) => Some(v),
                            Err(_) => return Err(format!("[output-format] unable to parse padding of '{}'", p_str)),
                        }
                    }
                } else {
                    None
                };
                tokens.push(OutputToken { is_placeholder: true, literal: String::new(), group: group_opt, padding: padding_opt });
                i = j+1;
            } else if c == '}' {
                return Err("[output-format] an unopened placeholder could not be closed by '}'".to_string());
            } else {
                literal.push(c);
                i+=1;
            }
        }
        if !literal.is_empty() {
            tokens.push(OutputToken { is_placeholder: false, literal, group: None, padding: None });
        }
        Ok(tokens)
    }

    fn format_output(tokens: &[OutputToken], captures: &HashMap<String, String>, auto_counter: &mut usize) -> String {
