                    *auto_counter += 1;
                }
                let mut val = captures.get(&group_key).cloned().unwrap_or_else(|| "".to_string());
                if let Some(pad) = token.padding {
                    if let Ok(num) = val.parse::<i64>() {
                        if num >= 0 && pad > 0 {
                            let s = num.to_string();
                            if s.len() < pad {
                                let zeros = "0".repeat(pad - s.len());
                                val = format!("{}{}", zeros, s);
                            }
                        }
                    }
                }
                result.push_str(&val);
            }
        }
        result
    }

    fn get_extension(filename: &str) -> Option<String> {
        if let Some(pos) = filename.rfind('.') {
            if pos == 0 {
                return None;
            }
            return Some(filename[pos..].to_string());
        }
        None
    }

    fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
        let mut ia = 0;
        let mut ib = 0;
        let ca: Vec<char> = a.chars().collect();
        let cb: Vec<char> = b.chars().collect();
        while ia < ca.len() && ib < cb.len() {
            let da = ca[ia].is_ascii_digit();
            let db = cb[ib].is_ascii_digit();
            if da && db {
                let mut ja = ia;
                while ja < ca.len() && ca[ja].is_ascii_digit() { ja+=1; }
                let mut jb = ib;
                while jb < cb.len() && cb[jb].is_ascii_digit() { jb+=1; }
                let sa: String = ca[ia..ja].iter().collect();
                let sb: String = cb[ib..jb].iter().collect();
                let na = sa.parse::<u64>().unwrap_or(0);
                let nb = sb.parse::<u64>().unwrap_or(0);
                match na.cmp(&nb) {
                    std::cmp::Ordering::Equal => {
                        match sa.len().cmp(&sb.len()) {
                            std::cmp::Ordering::Equal => {},
                            ord => return ord,
                        }
                    },
                    ord => return ord,
                }
                ia = ja;
                ib = jb;
            } else {
                match ca[ia].cmp(&cb[ib]) {
                    std::cmp::Ordering::Equal => { ia+=1; ib+=1; },
                    ord => return ord,
                }
            }
        }
        ca.len().cmp(&cb.len())
    }

    fn collect_file_entries(work_dir: &Path, depth: Option<usize>, max_depth: Option<usize>, regex_pat: &str, inferred: usize) -> Vec<String> {
        let file_target_raw = depth.unwrap_or(inferred);
        let dir_target_raw = max_depth.unwrap_or_else(|| depth.unwrap_or(inferred));
        let mut file_target = file_target_raw;
        let dir_target = dir_target_raw;
        if file_target > dir_target {
            file_target = dir_target;
        }

        let mut file_entries: Vec<(String, usize)> = Vec::new();
        let mut dir_entries: Vec<(String, usize)> = Vec::new();

        fn walk_dir(base: &Path, current: &Path, max_depth: usize, file_entries: &mut Vec<(String, usize)>, dir_entries: &mut Vec<(String, usize)>) {
            let read = match fs::read_dir(current) {
                Ok(r) => r,
                Err(_) => return,
            };
            for entry in read {
                if let Ok(e) = entry {
                    let file_name = e.file_name();
                    let entry_path = current.join(&file_name);
                    let rel_path = entry_path.strip_prefix(base).unwrap().to_string_lossy().replace('\\', "/");
                    let depth = rel_path.matches('/').count() + 1;
                    if depth > max_depth {
                        continue;
                    }
                    if let Ok(metadata) = e.metadata() {
                        if metadata.is_dir() {
                            dir_entries.push((rel_path.clone(), depth));
                            if depth < max_depth {
                                walk_dir(base, &entry_path, max_depth, file_entries, dir_entries);
                            }
                        } else {
                            file_entries.push((rel_path, depth));
                        }
                    }
                }
            }
        }

        walk_dir(work_dir, work_dir, dir_target, &mut file_entries, &mut dir_entries);

        let re = match Regex::new(regex_pat) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: regex parse error:\n    {}\n    ^\nerror: {}", regex_pat, e);
                process::exit(1);
            }
        };

        let mut files_by_depth: BTreeMap<usize, Vec<String>> = BTreeMap::new();
        for (path, d) in &file_entries {
            if re.is_match(path) {
                files_by_depth.entry(*d).or_default().push(path.clone());
            }
        }

        let mut matched_dirs: Vec<String> = Vec::new();
        for (path, d) in &dir_entries {
            if *d == dir_target && re.is_match(path) {
                matched_dirs.push(path.clone());
            }
        }
        if dir_target == 0 && re.is_match("") {
            matched_dirs.push("".to_string());
        }

        let mut matched_files: Vec<String> = Vec::new();
        for d in file_target..=dir_target {
            if let Some(v) = files_by_depth.get(&d) {
                if !v.is_empty() {
                    matched_files = v.clone();
                    break;
                }
            }
        }

        let mut result = Vec::new();
        result.extend(matched_dirs);
        result.extend(matched_files);
        result
    }

    fn print_table(entries: &[(String,String)]) {
        if entries.is_empty() {
            return;
        }
        let mut max_input = "Input".len();
        let mut max_output = "Output".len();
        for (inp, out) in entries {
            if inp.len() > max_input {
                max_input = inp.len();
            }
            if out.len() > max_output {
                max_output = out.len();
            }
        }
        let border = format!("+{}+{}+", "-".repeat(max_input+2), "-".repeat(max_output+2));
        println!("{}", border);
        println!("| {:<width$} | {:<width2$} |", "Input", "Output", width = max_input, width2 = max_output);
        println!("{}", border);
        for (inp, out) in entries {
            println!("| {:<width$} | {:<width2$} |", inp, out, width = max_input, width2 = max_output);
        }
        println!("{}", border);
    }

    // Map mode pure
    if has_map && !has_sort && !has_regex_flag {
        let map_path_raw = map_opt.clone().unwrap();
        let map_path_buf = PathBuf::from(&map_path_raw);
        let map_full_path = if map_path_buf.is_absolute() { map_path_buf } else { work_dir.join(&map_path_buf) };
        let map_content = match fs::read_to_string(&map_full_path) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("error: No such file or directory (os error 2)");
                process::exit(1);
            }
        };
        let map_json: serde_json::Value = match serde_json::from_str(&map_content) {
            Ok(v) => v,
            Err(_) => serde_json::Value::Object(serde_json::Map::new()),
        };
        let mut entries_sorted: Vec<(String,String)> = Vec::new();
        if let Some(obj) = map_json.as_object() {
            for (k,v) in obj {
                if let Some(val_str) = v.as_str() {
                    entries_sorted.push((k.clone(), val_str.to_string()));
                }
            }
        }
        entries_sorted.sort_by(|a,b| a.0.cmp(&b.0));

        let mut table_entries: Vec<(String,String)> = Vec::new();
        let mut output_map: BTreeMap<String,String> = BTreeMap::new();
        let mut had_rename_error = false;

        if test_flag {
            for (input, output) in &entries_sorted {
                let mut final_out = output.clone();
                if !overwrite_flag && final_out != *input {
                    loop {
                        let check_path = work_dir.join(&final_out);
                        if !check_path.exists() {
                            break;
                        }
                        let p = Path::new(&final_out);
                        let parent = p.parent();
                        let file_name = p.file_name().unwrap_or(OsStr::new(&final_out)).to_string_lossy().to_string();
                        let new_file_name = format!("_{}", file_name);
                        final_out = if let Some(par) = parent {
                            if par == Path::new("") { new_file_name } else { format!("{}/{}", par.to_string_lossy().replace('\\',"/"), new_file_name) }
                        } else { new_file_name };
                    }
                }
                table_entries.push((input.clone(), final_out.clone()));
                output_map.insert(final_out.clone(), input.clone());
            }
            // Deduplicate test mode? In our earlier map test with duplicate outputs, test mode showed multiple? For map mode test, we haven't tested duplicate outputs case.
            // For consistency, test mode for map should also deduplicate? Let's deduplicate by output keeping last input order.
            let mut dedup: BTreeMap<String,String> = BTreeMap::new();
            for (inp, outp) in &table_entries {
                dedup.insert(outp.clone(), inp.clone());
            }
            let mut dedup_table: Vec<(String,String)> = Vec::new();
            for (outp, inp) in &dedup {
                dedup_table.push((inp.clone(), outp.clone()));
            }
            dedup_table.sort_by(|a,b| a.1.cmp(&b.1));
            table_entries = dedup_table;
            // output_map is already deduped? Actually output_map for generate should be final outputs -> inputs, which for test mode is deduped version.
            output_map = dedup;
        } else {
            let mut created: HashSet<String> = HashSet::new();
            let mut processed: Vec<(String,String)> = Vec::new();
            for (input, output) in &entries_sorted {
                let mut final_out = output.clone();
                if final_out != *input && !overwrite_flag {
                    loop {
                        let check_path = work_dir.join(&final_out);
                        let exists_original = check_path.exists();
                        let exists_created = created.contains(&final_out);
                        if !exists_original && !exists_created {
                            break;
                        }
                        let p = Path::new(&final_out);
                        let parent = p.parent();
                        let file_name = p.file_name().unwrap_or(OsStr::new(&final_out)).to_string_lossy().to_string();
                        let new_file_name = format!("_{}", file_name);
                        final_out = if let Some(par) = parent {
                            if par == Path::new("") { new_file_name } else { format!("{}/{}", par.to_string_lossy().replace('\\',"/"), new_file_name) }
                        } else { new_file_name };
                    }
                }
                processed.push((input.clone(), final_out.clone()));
                created.insert(final_out.clone());
            }
            // For actual map, table sorted by output ascending
            let mut sorted = processed.clone();
            sorted.sort_by(|a,b| a.1.cmp(&b.1));
            table_entries = sorted.clone();
            for (inp, outp) in &table_entries {
                output_map.insert(outp.clone(), inp.clone());
            }

            // Perform renames in processed order
            for (input, final_out) in &processed {
                let src = work_dir.join(input);
                let dst = work_dir.join(final_out);
                if mkdir_flag {
                    if let Some(parent) = dst.parent() {
                        let _ = fs::create_dir_all(parent);
                    }
                }
                if !src.exists() {
                    eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", input);
                    had_rename_error = true;
                    continue;
                }
                match fs::rename(&src, &dst) {
                    Ok(_) => {},
                    Err(e) => {
                        had_rename_error = true;
                        eprintln!("[error] unable to rename '{}': {} (os error {})", input, e.to_string().split(" (os error").next().unwrap_or(&e.to_string()).trim(), e.raw_os_error().unwrap_or(2));
                    }
                }
            }
        }

        if !quiet_flag && !had_rename_error {
            table_entries.sort_by(|a,b| a.1.cmp(&b.1));
            print_table(&table_entries);
        } else if !quiet_flag && had_rename_error {
            // For map mode with error, original didn't print table for subdir case, so we only print errors (already printed) and no table.
            // But for map mode where input doesn't exist, it did print table? Let's see earlier for map with nonexist, test mode printed table, actual mode would print error plus table? We saw earlier map subdir error case: old printed only error, no table. So we suppress table on rename error.
        }

        if let Some(gen_path) = generate_opt {
            let gen_path_buf = PathBuf::from(&gen_path);
            let final_gen_path = if gen_path_buf.is_absolute() { gen_path_buf } else { work_dir.join(gen_path_buf) };
            if mkdir_flag {
                if let Some(parent) = final_gen_path.parent() {
                    let _ = fs::create_dir_all(parent);
                }
            }
            match fs::write(&final_gen_path, serde_json::to_string_pretty(&output_map).unwrap_or("{}".to_string())) {
                Ok(_) => {},
                Err(_) => {
                    eprintln!("error: No such file or directory (os error 2)");
                    process::exit(1);
                }
            }
        }
        return;
    }

    // Regex and sort modes
    let mut regex_pat_opt: Option<String> = None;
    let mut out_pat_str = String::new();
    let mut sort_order_opt: Option<String> = None;

    if has_sort {
        out_pat_str = positional.get(0).cloned().unwrap_or_default();
        if let Some(r) = regex_opt.clone() {
            regex_pat_opt = Some(r);
        }
        sort_order_opt = sort_opt.clone();
    } else if has_regex_flag {
        regex_pat_opt = regex_opt.clone();
        out_pat_str = positional.get(0).cloned().unwrap_or_default();
        sort_order_opt = sort_opt.clone();
    } else {
        if positional.len() >= 2 {
            let src = positional[positional.len()-2].clone();
            let outp = positional[positional.len()-1].clone();
            regex_pat_opt = Some(src);
            out_pat_str = outp;
        }
    }

    let tokens = match parse_output_pattern(&out_pat_str) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
    };

    let mut input_files: Vec<String> = Vec::new();
    if has_sort {
        let read = fs::read_dir(&work_dir).unwrap_or_else(|_| {
            eprintln!("error: No such file or directory (os error 2)");
            process::exit(1);
        });
        for entry in read {
            if let Ok(e) = entry {
                let name = e.file_name().to_string_lossy().to_string();
                input_files.push(name);
            }
        }
        if let Some(ref pat) = regex_pat_opt {
            let re = match Regex::new(pat) {
                Ok(r) => r,
                Err(e) => {
                    eprintln!("error: regex parse error:\n    {}\n    ^\nerror: {}", pat, e);
                    process::exit(1);
                }
            };
            input_files.retain(|f| re.is_match(f));
        }
        let order = sort_order_opt.as_deref().unwrap_or("asc");
        if order == "asc" {
            input_files.sort_by(|a,b| natural_cmp(a,b));
        } else {
            input_files.sort_by(|a,b| natural_cmp(b,a));
        }
    } else {
        let pat = regex_pat_opt.clone().unwrap();
        let inferred = pat.matches('/').count() + 1;
        input_files = collect_file_entries(&work_dir, depth_opt, max_depth_opt, &pat, inferred);
        if let Some(order) = sort_order_opt.clone() {
            if order == "asc" {
                input_files.sort_by(|a,b| natural_cmp(a,b));
            } else {
                input_files.sort_by(|a,b| natural_cmp(b,a));
            }
        } else {
            input_files.sort_by(|a,b| natural_cmp(a,b));
        }
    }

    let mut raw_entries: Vec<(String, String)> = Vec::new();

    if has_sort && regex_pat_opt.is_none() {
        for (idx, input) in input_files.iter().enumerate() {
            let mut captures: HashMap<String, String> = HashMap::new();
            captures.insert("0".to_string(), input.clone());
            captures.insert("1".to_string(), (idx+1).to_string());
            let mut auto_counter = 1;
            let formatted = format_output(&tokens, &captures, &mut auto_counter);
            let mut final_out = formatted;
            if !no_ext {
                let base = Path::new(input).file_name().unwrap_or(OsStr::new(input)).to_string_lossy().to_string();
                if let Some(ext) = get_extension(&base) {
                    final_out.push_str(&ext);
                }
            }
            raw_entries.push((input.clone(), final_out));
        }
    } else {
        let pat = regex_pat_opt.clone().unwrap();
        let re = match Regex::new(&pat) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: regex parse error:\n    {}\n    ^\nerror: {}", pat, e);
                process::exit(1);
            }
        };
        for (_idx, input) in input_files.iter().enumerate() {
            if let Some(caps) = re.captures(input) {
                let mut captures: HashMap<String, String> = HashMap::new();
                captures.insert("0".to_string(), caps.get(0).map(|m| m.as_str().to_string()).unwrap_or_default());
                for i in 1..caps.len() {
                    if let Some(m) = caps.get(i) {
                        captures.insert(i.to_string(), m.as_str().to_string());
                    } else {
                        captures.insert(i.to_string(), "".to_string());
                    }
                }
                for name in re.capture_names().flatten() {
                    if let Some(m) = caps.name(name) {
                        captures.insert(name.to_string(), m.as_str().to_string());
                    }
                }
                let mut auto_counter = 1;
                let formatted = format_output(&tokens, &captures, &mut auto_counter);
                let mut final_out = formatted;
                if !no_ext {
                    let base = Path::new(input).file_name().unwrap_or(OsStr::new(input)).to_string_lossy().to_string();
                    if let Some(ext) = get_extension(&base) {
                        final_out.push_str(&ext);
                    }
                }
                raw_entries.push((input.clone(), final_out));
            }
        }
    }

    // Collision handling
    let mut table_entries: Vec<(String,String)> = Vec::new();
    let mut output_map: BTreeMap<String,String> = BTreeMap::new();
    let mut had_rename_error = false;

    if test_flag {
        let mut map: BTreeMap<String,String> = BTreeMap::new();
        for (input, output) in &raw_entries {
            let mut final_out = output.clone();
            if !overwrite_flag && final_out != *input {
                loop {
                    let check_path = work_dir.join(&final_out);
                    if !check_path.exists() {
                        break;
                    }
                    let p = Path::new(&final_out);
                    let parent = p.parent();
                    let file_name = p.file_name().unwrap_or(OsStr::new(&final_out)).to_string_lossy().to_string();
                    let new_file_name = format!("_{}", file_name);
                    final_out = if let Some(par) = parent {
                        if par == Path::new("") { new_file_name } else { format!("{}/{}", par.to_string_lossy().replace('\\',"/"), new_file_name) }
                    } else { new_file_name };
                }
            }
            map.insert(final_out.clone(), input.clone());
        }
        for (outp, inp) in &map {
            table_entries.push((inp.clone(), outp.clone()));
            output_map.insert(outp.clone(), inp.clone());
        }
        table_entries.sort_by(|a,b| a.1.cmp(&b.1));
    } else {
        // actual
        let mut created: HashSet<String> = HashSet::new();
        let mut processed: Vec<(String,String)> = Vec::new();
        for (input, output) in &raw_entries {
            let mut final_out = output.clone();
            if final_out != *input && !overwrite_flag {
                loop {
                    let check_path = work_dir.join(&final_out);
                    let exists_original = check_path.exists();
                    let exists_created = created.contains(&final_out);
                    if !exists_original && !exists_created {
                        break;
                    }
                    let p = Path::new(&final_out);
                    let parent = p.parent();
                    let file_name = p.file_name().unwrap_or(OsStr::new(&final_out)).to_string_lossy().to_string();
                    let new_file_name = format!("_{}", file_name);
                    final_out = if let Some(par) = parent {
                        if par == Path::new("") { new_file_name } else { format!("{}/{}", par.to_string_lossy().replace('\\',"/"), new_file_name) }
                    } else { new_file_name };
                }
            }
            processed.push((input.clone(), final_out.clone()));
            created.insert(final_out.clone());
        }

        // For overwrite flag, deduplicate processed by output keeping last
        let mut final_processed = processed.clone();
        if overwrite_flag {
            let mut dedup: BTreeMap<String, String> = BTreeMap::new();
            for (inp, outp) in &processed {
                dedup.insert(outp.clone(), inp.clone());
            }
            final_processed.clear();
            for (outp, inp) in &dedup {
                final_processed.push((inp.clone(), outp.clone()));
            }
        }

        // Table sorted by output ascending
        let mut sorted = final_processed.clone();
        sorted.sort_by(|a,b| a.1.cmp(&b.1));
        table_entries = sorted;

        for (inp, outp) in &table_entries {
            output_map.insert(outp.clone(), inp.clone());
        }

        // Perform renames in processed order (original input order) but with dedup handling for overwrite
        // For overwrite true, we should rename in processed order, overwriting
        for (input, final_out) in &processed {
            // If overwrite true and this input is not the last for its output, it will be overwritten later, but we still rename?
            // In original, for overwrite same case, only last file remained, meaning all renames happened in order, overwriting.
            // So we should still attempt rename for each entry in processed order.
            let src = work_dir.join(input);
            let dst = work_dir.join(final_out);
            if mkdir_flag {
                if let Some(parent) = dst.parent() {
                    let _ = fs::create_dir_all(parent);
                }
            }
            if !src.exists() {
                eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", input);
                had_rename_error = true;
                continue;
            }
            // If dst parent doesn't exist and mkdir false, then rename fails
            if !mkdir_flag {
                if let Some(parent) = dst.parent() {
                    if parent != Path::new("") && !work_dir.join(parent).exists() {
                        eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", input);
                        had_rename_error = true;
                        continue;
                    }
                }
            }
            match fs::rename(&src, &dst) {
                Ok(_) => {},
                Err(e) => {
                    had_rename_error = true;
                    // For simplicity, print as original
                    let msg = e.to_string();
                    if msg.contains("No such file or directory") {
                        eprintln!("[error] unable to rename '{}': No such file or directory (os error 2)", input);
                    } else if msg.contains("Invalid argument") || msg.contains("Is a directory") {
                        eprintln!("[error] unable to rename '{}': Invalid argument (os error 22)", input);
                    } else {
                        eprintln!("[error] unable to rename '{}': {} (os error {})", input, msg, e.raw_os_error().unwrap_or(2));
                    }
                }
            }
        }

        // If overwrite flag, table should be deduplicated version (final_processed sorted) which we already have as table_entries
        // For non-overwrite, table_entries is sorted processed (which is unique due to underscore handling)
    }

    if !quiet_flag && !had_rename_error {
        print_table(&table_entries);
    } else if !quiet_flag && had_rename_error {
        // For cases where rename failed due to missing dir, original didn't print table. So we suppress table if had error and mkdir false? But for other errors like nonexist input, it did print table? In map mode with nonexist input, it printed error plus table? Let's check earlier: map with nonexist input, we had table plus error? Actually we didn't test actual mode for that.
        // For simplicity, if had error due to missing parent (mkdir false), don't print table. Otherwise print table? Let's only print table if no error, or if error is not due to missing dir?
        // We'll check: if had_rename_error and not mkdir_flag, don't print table (as per observed). If mkdir_flag and still error (like Invalid argument), original also didn't print table for map subdir case even with -k? Actually map subdir with -k still errored and didn't print table. So we should not print table when any rename error occurred, regardless?
        // For map subdir with -k, old printed only error, no table. So any rename error suppresses table.
        // So we will suppress table when had_rename_error true.
    }

    if let Some(gen_path) = generate_opt {
        let gen_path_buf = PathBuf::from(&gen_path);
        let final_gen_path = if gen_path_buf.is_absolute() { gen_path_buf } else { work_dir.join(gen_path_buf) };
        if mkdir_flag {
            if let Some(parent) = final_gen_path.parent() {
                let _ = fs::create_dir_all(parent);
