        }
        sort_order_opt = sort_opt.clone();
    } else if has_regex_flag {
        regex_pat_opt = regex_opt.clone();
        out_pat_str = positional.get(0).cloned().unwrap_or_default();
        sort_order_opt = sort_opt.clone();
    } else {
        if positional.len() >= 2 {
            let src = positional[positional.len()-2].clone();
            let outp = positional[positional.len()-1].clone();
            regex_pat_opt = Some(src);
            out_pat_str = outp;
