    let mut input_files: Vec<String> = Vec::new();
    if has_sort {
        let read = fs::read_dir(&work_dir).unwrap_or_else(|_| {
            eprintln!("error: No such file or directory (os error 2)");
            process::exit(1);
        });
        for entry in read {
            if let Ok(e) = entry {
                let name = e.file_name().to_string_lossy().to_string();
                input_files.push(name);
            }
        }
        if let Some(ref pat) = regex_pat_opt {
            let re = match Regex::new(pat) {
                Ok(r) => r,
                Err(e) => {
                    eprintln!("error: regex parse error:\n    {}\n    ^\nerror: {}", pat, e);
                    process::exit(1);
                }
            };
            input_files.retain(|f| re.is_match(f));
        }
        let order = sort_order_opt.as_deref().unwrap_or("asc");
        if order == "asc" {
            input_files.sort_by(|a,b| natural_cmp(a,b));
        } else {
            input_files.sort_by(|a,b| natural_cmp(b,a));
        }
    } else {
        let pat = regex_pat_opt.clone().unwrap();
        let inferred = pat.matches('/').count() + 1;
        input_files = collect_file_entries(&work_dir, depth_opt, max_depth_opt, &pat, inferred);
        if let Some(order) = sort_order_opt.clone() {
            if order == "asc" {
                input_files.sort_by(|a,b| natural_cmp(a,b));
            } else {
                input_files.sort_by(|a,b| natural_cmp(b,a));
            }
        } else {
            input_files.sort_by(|a,b| natural_cmp(a,b));
        }
    }

    let mut raw_entries: Vec<(String, String)> = Vec::new();

    if has_sort && regex_pat_opt.is_none() {
        for (idx, input) in input_files.iter().enumerate() {
            let mut captures: HashMap<String, String> = HashMap::new();
            captures.insert("0".to_string(), input.clone());
            captures.insert("1".to_string(), (idx+1).to_string());
            let mut auto_counter = 1;
            let formatted = format_output(&tokens, &captures, &mut auto_counter);
            let mut final_out = formatted;
            if !no_ext {
                let base = Path::new(input).file_name().unwrap_or(OsStr::new(input)).to_string_lossy().to_string();
                if let Some(ext) = get_extension(&base) {
                    final_out.push_str(&ext);
                }
            }
            raw_entries.push((input.clone(), final_out));
        }
    } else {
        let pat = regex_pat_opt.clone().unwrap();
        let re = match Regex::new(&pat) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: regex parse error:\n    {}\n    ^\nerror: {}", pat, e);
                process::exit(1);
            }
        };
        for (_idx, input) in input_files.iter().enumerate() {
            if let Some(caps) = re.captures(input) {
                let mut captures: HashMap<String, String> = HashMap::new();
                captures.insert("0".to_string(), caps.get(0).map(|m| m.as_str().to_string()).unwrap_or_default());
                for i in 1..caps.len() {
                    if let Some(m) = caps.get(i) {
                        captures.insert(i.to_string(), m.as_str().to_string());
                    } else {
                        captures.insert(i.to_string(), "".to_string());
                    }
                }
                for name in re.capture_names().flatten() {
                    if let Some(m) = caps.name(name) {
                        captures.insert(name.to_string(), m.as_str().to_string());
                    }
                }
                let mut auto_counter = 1;
                let formatted = format_output(&tokens, &captures, &mut auto_counter);
                let mut final_out = formatted;
                if !no_ext {
                    let base = Path::new(input).file_name().unwrap_or(OsStr::new(input)).to_string_lossy().to_string();
                    if let Some(ext) = get_extension(&base) {
                        final_out.push_str(&ext);
                    }
                }
                raw_entries.push((input.clone(), final_out));
            }
        }
    }

    let mut table_entries: Vec<(String,String)> = Vec::new();
    let mut output_map: BTreeMap<String,String> = BTreeMap::new();
    let mut had_rename_error = false;

    if test_flag {
