    fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
        let mut ia = 0;
        let mut ib = 0;
        let ca: Vec<char> = a.chars().collect();
        let cb: Vec<char> = b.chars().collect();
        while ia < ca.len() && ib < cb.len() {
            let da = ca[ia].is_ascii_digit();
            let db = cb[ib].is_ascii_digit();
            if da && db {
                let mut ja = ia;
                while ja < ca.len() && ca[ja].is_ascii_digit() { ja+=1; }
                let mut jb = ib;
                while jb < cb.len() && cb[jb].is_ascii_digit() { jb+=1; }
                let sa: String = ca[ia..ja].iter().collect();
                let sb: String = cb[ib..jb].iter().collect();
                let na = sa.parse::<u64>().unwrap_or(0);
                let nb = sb.parse::<u64>().unwrap_or(0);
                match na.cmp(&nb) {
                    std::cmp::Ordering::Equal => {
                        match sa.len().cmp(&sb.len()) {
                            std::cmp::Ordering::Equal => {},
                            ord => return ord,
                        }
                    },
                    ord => return ord,
                }
                ia = ja;
                ib = jb;
            } else {
                match ca[ia].cmp(&cb[ib]) {
                    std::cmp::Ordering::Equal => { ia+=1; ib+=1; },
                    ord => return ord,
                }
            }
        }
        ca.len().cmp(&cb.len())
    }

    fn collect_file_entries(work_dir: &Path, depth: Option<usize>, max_depth: Option<usize>, regex_pat: &str, inferred: usize) -> Vec<String> {
        let file_target_raw = depth.unwrap_or(inferred);
        let dir_target_raw = max_depth.unwrap_or_else(|| depth.unwrap_or(inferred));
